<?php
require 'config.php'; require_login();
$u=$_SESSION['user']; if($u['role']==='admin'){header('Location: admin.php');exit;} if($u['role']==='faculty'){header('Location: faculty.php');exit;}
$title='Dashboard'; $term=selected_term($pdo); $termId=$term?(int)$term['id']:0;
$subjectCount=$pdo->prepare("SELECT COUNT(*) FROM enrollments WHERE student_id=? AND status='approved' AND term_id=?");$subjectCount->execute([$u['id'],$termId]);$subjects=(int)$subjectCount->fetchColumn();
$unitsQ=$pdo->prepare("SELECT COALESCE(SUM(s.units),0) FROM enrollments e JOIN subjects s ON s.id=e.subject_id WHERE e.student_id=? AND e.status='approved' AND e.term_id=?");$unitsQ->execute([$u['id'],$termId]);$units=(int)$unitsQ->fetchColumn();
$t=$pdo->prepare("SELECT COUNT(*) FROM tickets WHERE student_id=? AND status NOT IN ('Resolved','Rejected')");$t->execute([$u['id']]);$tickets=(int)$t->fetchColumn();
$pending=$pdo->prepare("SELECT COUNT(*) FROM enrollments WHERE student_id=? AND status='pending' AND term_id=?");$pending->execute([$u['id'],$termId]);$pending=(int)$pending->fetchColumn();
$anns=$pdo->query("SELECT * FROM announcements ORDER BY created_at DESC LIMIT 4")->fetchAll();
$sched=$pdo->prepare("SELECT s.*,sub.code,sub.name FROM schedules s JOIN subjects sub ON sub.id=s.subject_id WHERE s.student_id=? AND s.term_id=? ORDER BY FIELD(s.day_name,'Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'),s.start_time");$sched->execute([$u['id'],$termId]);$sched=$sched->fetchAll();
$recentNot=[];try{$q=$pdo->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 3');$q->execute([$u['id']]);$recentNot=$q->fetchAll();}catch(PDOException $e){}
$reminders=[['Enrollment deadline','Review your preferred schedules before submitting an enrollment request.','enrollment.php'],['Ticket follow-up','Check My Ticket for the latest administration responses.','tickets.php'],['Academic schedule','Keep your weekly schedule handy for class days and rooms.','schedule.php']];
function stat_card($label,$value,$link,$color='blue'){return '<div class="card stat"><span class="muted">'.e($label).'</span><div class="num '.e($color).'">'.e($value).'</div><a class="stat-link" href="'.e($link).'">View details →</a></div>';}
require 'header.php';
?>
<div class="dashboard-intro"><div><p class="muted">Good morning, <?=e(explode(' ',$u['name'])[0])?>! Here's what's happening in your account today.</p><span class="term-context">Viewing: <?=e($term['label']??'Academic Term')?></span></div><a class="btn subtle-btn" href="profile.php">View My Profile</a></div>
<div class="student-card"><div class="student-card-avatar"><?php if(!empty($u['avatar_path'])):?><img src="<?=e($u['avatar_path'])?>" alt="Profile picture"><?php else:?><?=e(strtoupper(substr($u['name'],0,1)))?><?php endif;?></div><div class="student-card-main"><div class="eyebrow">STUDENT INFORMATION</div><h2><?=e($u['name'])?></h2><p><?=e($u['program'] ?: 'Program not set')?> · Student ID: <b><?=e($u['student_id'] ?: '—')?></b></p></div><div class="student-status"><span>Account</span><b>Active</b></div></div>
<div class="cards"><?=stat_card('Enrolled Subjects',$subjects,'enrollment.php','blue')?><?=stat_card('Total Units',$units,'enrollment.php','green')?><?=stat_card('Pending Enrollment',$pending,'enrollment.php','orange')?><?=stat_card('Active Tickets',$tickets,'tickets.php','purple')?></div>
<div class="quick-actions"><div class="quick-title"><span class="eyebrow">QUICK ACTIONS</span><b>Common student tasks</b></div><a href="enrollment.php">Enroll in a Subject <span>→</span></a><a href="schedule.php">View My Schedule <span>→</span></a><a href="grades.php">View Grades <span>→</span></a><a href="documents.php">Document Center <span>→</span></a><a href="attendance.php">View Attendance <span>→</span></a><a href="tickets.php">Submit a Ticket <span>→</span></a><a href="important_dates.php">Important Dates <span>→</span></a></div>
<div class="grid"><div class="card"><div class="card-head"><h3>My Schedule</h3><a href="schedule.php">View Full Schedule →</a></div><?php if(!$sched):?><p class="muted">No enrolled subjects for this term.</p><?php endif;?><?php foreach(array_slice($sched,0,6) as $s):?><div class="list-row"><span><b><?=e($s['code'])?> — <?=e($s['name'])?></b><small><?=e($s['day_name'])?> · <?=e($s['room'])?></small></span><b><?=date('g:i A',strtotime($s['start_time']))?> – <?=date('g:i A',strtotime($s['end_time']))?></b></div><?php endforeach;?></div>
<div class="card"><div class="card-head"><h3>Recent Announcements</h3><a href="announcements.php">View All →</a></div><?php foreach($anns as $a):?><div class="list-row clickable-row" onclick="location.href='announcements.php?id=<?=e($a['id'])?>'"><span><b><?=e($a['title'])?></b><small><?=e(mb_strimwidth($a['body'],0,72,'…'))?></small></span><small><?=date('M d',strtotime($a['created_at']))?></small></div><?php endforeach;?></div></div>
<div class="dashboard-lower"><div class="section reminder-panel"><div class="card-head"><h3>Important Reminders</h3><span class="muted">Stay on top of your tasks</span></div><?php foreach($reminders as $r):?><a class="reminder-row" href="<?=e($r[2])?>"><span class="reminder-mark">!</span><span><b><?=e($r[0])?></b><small><?=e($r[1])?></small></span><span>→</span></a><?php endforeach;?></div>
<?php if($recentNot):?><div class="section"><div class="card-head"><h3>Recent Notifications</h3><a href="notifications.php">View All →</a></div><?php foreach($recentNot as $n):?><div class="notification-mini"><span class="notification-dot"></span><div><b><?=e($n['title'])?></b><p><?=e($n['message'])?></p><small class="muted"><?=date('M d, Y · g:i A',strtotime($n['created_at']))?></small></div></div><?php endforeach;?></div><?php endif;?></div>
<?php require 'footer.php'; ?>
